typedef union {
    uint8_t  u8[16];
    uint32_t u32[4];
    int32_t  i32[4];
    uint64_t u64[2];
} lk_xmm_t;

static inline uint8_t lk_ld8(uint64_t a) {
    return *(const uint8_t *)(uintptr_t)a;
}
static inline uint16_t lk_ld16(uint64_t a) {
    uint16_t v;
    memcpy(&v, (const void *)(uintptr_t)a, 2);
    return v;
}
static inline uint32_t lk_ld32(uint64_t a) {
    uint32_t v;
    memcpy(&v, (const void *)(uintptr_t)a, 4);
    return v;
}
static inline uint64_t lk_ld64(uint64_t a) {
    uint64_t v;
    memcpy(&v, (const void *)(uintptr_t)a, 8);
    return v;
}
static inline void lk_st8(uint64_t a, uint8_t v) {
    *(uint8_t *)(uintptr_t)a = v;
}
static inline void lk_st16(uint64_t a, uint16_t v) {
    memcpy((void *)(uintptr_t)a, &v, 2);
}
static inline void lk_st32(uint64_t a, uint32_t v) {
    memcpy((void *)(uintptr_t)a, &v, 4);
}
static inline void lk_st64(uint64_t a, uint64_t v) {
    memcpy((void *)(uintptr_t)a, &v, 8);
}
static inline lk_xmm_t lk_ld128(uint64_t a) {
    lk_xmm_t v;
    memcpy(&v, (const void *)(uintptr_t)a, 16);
    return v;
}
static inline void lk_st128(uint64_t a, lk_xmm_t v) {
    memcpy((void *)(uintptr_t)a, &v, 16);
}

